{
    [Fact]
    public void GoldCustomerWithHundredDollarSubtotalPaysNinetyFive()
    {
        var handler = new CheckoutPricingHandler();

        var result = handler.Handle(new CheckoutPricingRequest(CustomerTier.Gold, 100.00m));

        Assert.Equal(95.00m, result.Total);
